// Load the npm packages
import * as dynamoose from "dynamoose";

// Load the local model constants and base model functionalities
import { DB_CONSTANTS } from "../DB.constants";

// Import Base Dto
import { BaseDbDto } from "./Base.model";

// Import Enums
import { CorporateUserTypeEnum } from "../../enums/CorporateUser.enum";

class DbCorporateUserDto extends BaseDbDto {
  GSI1PK!: string;
  GSI1SK!: string;

  /**
   * The `id` field will be the unique id,
   * The `id` will be generated by converting the `cognitoUserId` using
   * `uuidToULID()` method
   */
  id!: string;

  // refrences
  cognitoUserId!: string;
  companyId!: string;
  inviteId!: string;

  email!: string;
  firstName!: string;
  lastName!: string;
  corporateUserType!: CorporateUserTypeEnum;

  // Audit
  updatedByUserId?: string;
  deletedByUserId?: string;

  /**
   * The `updatedByCorporateUserId` attribute represents the ID of the corporate user who updated the corporate user details,
   * While updating a corporate user details, the `userId` recieved from the authorizer context will be the `cognito user id`,
   * In the backend, the `userId` will be converted by using `uuidToULID()` method to access the details of the user
   * who updated the corporate user details from the `CorporateUser` model.
   */
  updatedByCorporateUserId?: string;

  /**
   * The `deletedByCorporateUserId` attribute represents the ID of the corporate user who deleted the corporate user,
   * While deleting a corporate user, the `userId` recieved from the authorizer context will be the `cognito user id`,
   * In the backend, the `userId` will be converted by using `uuidToULID()` method to access the details of the user
   * who deleted the corporate user from the `CorporateUser` model.
   */
  deletedByCorporateUserId?: string;

  isDeleted!: boolean;
}

// Creating a DynamoDB schema for the 'CorporateUserSchema' model with specified attributes and their types
const CorporateUserSchema = new dynamoose.Schema(
  {
    ...DB_CONSTANTS.WORKO_PK_SK,
    GSI1PK: {
      type: String,
      index: {
        name: "GSI1",
        type: "global",
        rangeKey: "GSI1SK",
      },
    },
    GSI1SK: {
      type: String,
      index: {
        name: "GSI1",
        type: "global",
      },
    },
    id: {
      type: String,
      required: true,
    },
    cognitoUserId: {
      type: String,
      required: true,
    },
    companyId: {
      type: String,
      required: true,
    },
    email: {
      type: String,
      required: true,
    },
    inviteId: {
      type: String,
      required: true,
    },
    firstName: {
      type: String,
      required: true,
    },
    lastName: {
      type: String,
      required: true,
    },
    corporateUserType: {
      type: String,
      required: true,
    },
    updatedByUserId: {
      type: String,
      required: false,
    },
    deletedByUserId: {
      type: String,
      required: false,
    },
    updatedByCorporateUserId: {
      type: String,
      required: false,
    },
    deletedByCorporateUserId: {
      type: String,
      required: false,
    },
    isDeleted: {
      type: Boolean,
      required: true,
    },
  },
  {
    ...DB_CONSTANTS.WORKO_MODEL_SCHEMA_OPTIONS,
  }
);

// Creating a DynamoDB model 'CompanyJobModel' based on the 'CompanyJobSchema' and registering it with the database model
const CorporateUserModel = dynamoose.model<DbCorporateUserDto>(
  "CorporateUser",
  CorporateUserSchema
);

// Exporting the 'CorporateUserModel' for external usage
export { CorporateUserModel, DbCorporateUserDto };
